  color: var(--color-danger);
  border-color: rgba(255, 92, 106, 0.3);
}
.btn-danger:hover {
  background: rgba(255, 92, 106, 0.2);
  border-color: rgba(255, 92, 106, 0.5);
}
.btn-danger:focus-visible {
  outline-color: var(--color-danger);
  box-shadow: 0 0 0 4px var(--color-danger-focus);
