(() => {
  const trigger = document.querySelector('.trigger');
  const dialog  = document.getElementById('delete-dialog');
  const cancelBtn  = document.getElementById('dialog-cancel');
  const confirmBtn = document.getElementById('dialog-confirm');

  // Open
  trigger.addEventListener('click', () => {
    dialog.showModal();
    cancelBtn.focus();
  });

  // Cancel — close and restore focus to trigger
  cancelBtn.addEventListener('click', closeDialog);

  // Confirm — perform deletion (demo: log + close)
  confirmBtn.addEventListener('click', () => {
    console.log('Image deleted.');
    closeDialog();
  });

  // Backdrop click closes dialog
  dialog.addEventListener('click', (e) => {
    if (e.target === dialog) closeDialog();
  });

  // Escape is handled natively by <dialog>; restore focus afterward
  dialog.addEventListener('close', () => trigger.focus());

  function closeDialog() {
    dialog.close();
    // 'close' event fires synchronously, focus already restored above
  }
})();

